27	static uint32_t now_ms(void)
28	{
29	    struct timespec ts;
30	    clock_gettime(CLOCK_MONOTONIC, &ts);
31	    return (uint32_t)((uint64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
32	}
