34	static int start_command(pid_t *pid, const char *cmd,
35	                         posix_spawn_file_actions_t *actions,
36	                         posix_spawnattr_t *attr)
37	{
38	#ifdef __NuttX__
39	#ifdef CONFIG_VG_HMI
40	    {
41	    /* Run linked applications directly: killing only an NSH wrapper would
42	     * leave its builtin child running and its pipe/locks alive. Product
43	     * commands have already passed the allowlist and metacharacter guard. */
44	    char *copy = strdup(cmd);
45	    char *args[40];
46	    char *save = NULL;
47	    int n = 0;
48	    int rc;
49	    if (!copy) return ENOMEM;
50	    for (char *p = strtok_r(copy, " \t", &save); p;
51	         p = strtok_r(NULL, " \t", &save)) {
52	        if (n == 39) { free(copy); return E2BIG; }
53	        args[n++] = p;
54	    }
55	    args[n] = NULL;
56	    const char *base = n ? strrchr(args[0], '/') : NULL;
57	    int index = n ? builtin_isavail(base ? base + 1 : args[0]) : -1;
58	    const struct builtin_s *app = index < 0 ? NULL : builtin_for_index(index);
59	    if (app) {
60	        rc = posix_spawnattr_setstacksize(attr, app->stacksize);
61	        if (!rc) {
62	            *pid = task_spawn(app->name, app->main, actions, attr,
63	                              args + 1, NULL);
64	            rc = *pid < 0 ? -*pid : 0;
65	        }
66	        free(copy);
67	        return rc;
68	    }
69	    free(copy);
70	    }
71	#endif
72	#ifdef CONFIG_SYSTEM_POPEN_SHPATH
73	    char *argv[] = {CONFIG_SYSTEM_POPEN_SHPATH, "-c", (char *)cmd, NULL};
74	    return posix_spawn(pid, argv[0], actions, attr, argv, NULL);
75	#else
76	    char *argv[] = {"-c", (char *)cmd, NULL};
77	    int rc = posix_spawnattr_setstacksize(attr, CONFIG_SYSTEM_POPEN_STACKSIZE);
78	    if (rc) return rc;
79	    *pid = task_spawn("agent_shell", nsh_system, actions, attr, argv, NULL);
80	    return *pid < 0 ? -*pid : 0;
81	#endif
82	#else
83	    extern char **environ;
84	    char *argv[] = {"sh", "-c", (char *)cmd, NULL};
85	    int rc = posix_spawnattr_setflags(attr, POSIX_SPAWN_SETPGROUP);
86	    if (!rc) rc = posix_spawnattr_setpgroup(attr, 0);
87	    return rc ? rc : posix_spawn(pid, "/bin/sh", actions, attr, argv, environ);
88	#endif
89	}
