91	int tool_shell_run(const char *command, char *out, size_t cap,
92	                   uint32_t timeout_ms)
93	{
94	    posix_spawn_file_actions_t actions;
95	    posix_spawnattr_t attr;
96	    int pipefd[2];
97	    pid_t pid = -1;
98	    int rc, status = 0;
99	    size_t used = 0;
100	    int overflow = 0, eof = 0, exited = 0;
101	    uint32_t started = now_ms();
102	    if (!command || !out || !cap || !timeout_ms) return -EINVAL;
103	    out[0] = 0;
104	    if (pipe(pipefd)) return -errno;
105	    if (fcntl(pipefd[0], F_SETFD, FD_CLOEXEC) < 0 ||
106	        fcntl(pipefd[1], F_SETFD, FD_CLOEXEC) < 0) {
107	        rc = errno;
108	        goto close_pipe;
109	    }
110	    rc = posix_spawn_file_actions_init(&actions);
111	    if (rc) goto close_pipe;
112	    rc = posix_spawnattr_init(&attr);
113	    if (rc) goto destroy_actions;
114	    if (!(rc = posix_spawn_file_actions_adddup2(&actions, pipefd[1], STDOUT_FILENO)) &&
115	        !(rc = posix_spawn_file_actions_addclose(&actions, pipefd[0])) &&
116	        !(rc = posix_spawn_file_actions_addclose(&actions, pipefd[1])))
117	        rc = start_command(&pid, command, &actions, &attr);
118	    posix_spawnattr_destroy(&attr);
119	    posix_spawn_file_actions_destroy(&actions);
120	    close(pipefd[1]);
121	    if (rc) { close(pipefd[0]); return -rc; }
122	    int flags = fcntl(pipefd[0], F_GETFL);
123	    if (flags < 0 || fcntl(pipefd[0], F_SETFL, flags | O_NONBLOCK) < 0) {
124	        rc = -errno;
125	        goto stop_child;
126	    }
127	    while (!exited || !eof) {
128	        if (now_ms() - started >= timeout_ms) { rc = -ETIMEDOUT; goto stop_child; }
129	        struct pollfd pfd = {pipefd[0], POLLIN, 0};
130	        if (!eof && poll(&pfd, 1, 10) < 0 && errno != EINTR) {
131	            rc = -errno;
132	            goto stop_child;
133	        }
134	        if (eof) usleep(1000);
135	        char chunk[256];
136	        ssize_t got = eof ? -1 : read(pipefd[0], chunk, sizeof(chunk));
137	        if (got > 0) {
138	            size_t n = (size_t)got;
139	            size_t room = cap - used - 1;
140	            if (n > room) { n = room; overflow = 1; }
141	            memcpy(out + used, chunk, n);
142	            used += n;
143	            out[used] = 0;
144	        } else if (got == 0) eof = 1;
145	        else if (!eof && errno != EAGAIN && errno != EINTR) {
146	            rc = -errno;
147	            goto stop_child;
148	        }
149	        if (!exited) {
150	            pid_t done = waitpid(pid, &status, WNOHANG);
151	            if (done == pid) exited = 1;
152	            else if (done < 0 && errno != EINTR) { rc = -errno; goto stop_child; }
153	        }
154	    }
155	    close(pipefd[0]);
156	    return overflow ? -EOVERFLOW :
157	        (WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 0 : -EIO);
158	
159	stop_child:
160	#ifndef __NuttX__
161	    kill(-pid, SIGKILL);
162	#else
163	    if (!exited) kill(pid, SIGKILL);
164	#endif
165	    /* SIGKILL termination is asynchronous; reap with a bounded wait. */
166	    uint32_t stop = now_ms();
167	    while (!exited && now_ms() - stop < 100) {
168	        pid_t done = waitpid(pid, &status, WNOHANG);
169	        if (done == pid || (done < 0 && errno == ECHILD)) exited = 1;
170	        else usleep(1000);
171	    }
172	    close(pipefd[0]);
173	    return rc;
174	destroy_actions:
175	    posix_spawn_file_actions_destroy(&actions);
176	close_pipe:
177	    close(pipefd[0]);
178	    close(pipefd[1]);
179	    return -rc;
180	}
