40	static size_t shell_append(char *out, size_t cap, size_t off,
41	                            const char *fmt, ...)
42	{
43	    if (!cap) return 0;
44	    if (off >= cap - 1) { out[cap - 1] = 0; return cap - 1; }
45	    va_list ap;
46	    va_start(ap, fmt);
47	    int n = vsnprintf(out + off, cap - off, fmt, ap);
48	    va_end(ap);
49	    if (n < 0 || (size_t)n >= cap - off) {
50	        out[off] = 0;
51	        syslog(LOG_WARNING, "[%s] metadata output truncated at %zu/%zu\n", TAG, off, cap);
52	        return cap - 1;
53	    }
54	    return off + (size_t)n;
55	}
