150	/* Shell meta-characters that could be used for injection */
151	#if AGENT_SHELL_SECURITY == AGENT_SHELL_SECURITY_ALLOWLIST
152	static bool has_shell_meta(const char *cmd)
153	{
154	    const char *meta = "|;&`$(){}><\n\\";
155	    for (const char *p = cmd; *p; p++) {
156	        if (strchr(meta, *p)) return true;
157	    }
158	    return false;
159	}
