162	static int is_blocked(const char *cmd)
163	{
164	#if AGENT_SHELL_SECURITY == AGENT_SHELL_SECURITY_DENY
165	    /* Deny mode: block everything */
166	    return 1;
167	#elif AGENT_SHELL_SECURITY == AGENT_SHELL_SECURITY_FULL
168	    /* Full mode: allow most commands, only block critical ones.
169	     * This mode is designed for skill authoring and development.
170	     * Skills can use pipes, redirects, and command chaining. */
171	    
172	    /* Extract command name */
173	    char first[64];
174	    int i = 0;
175	    while (cmd[i] == ' ') i++;
176	    int j = 0;
177	    while (cmd[i] && cmd[i] != ' ' && j < (int)sizeof(first) - 1)
178	        first[j++] = cmd[i++];
179	    first[j] = '\0';
180	
181	    /* Strip path prefix: /bin/rm -> rm */
182	    const char *basename = strrchr(first, '/');
183	    const char *name = basename ? basename + 1 : first;
184	
185	    /* Block critical commands only */
186	    for (int k = 0; s_critical[k]; k++) {
187	        if (strcmp(name, s_critical[k]) == 0)
188	            return 1;
189	    }
190	    
191	    return 0;  /* allow */
192	#else
193	    /* Allowlist mode (default): strict whitelist + no shell meta-characters.
194	     * This is the production-safe mode. */
195	    
196	    /* Reject any shell meta-characters (pipe, redirect, subshell, etc.) */
197	    if (has_shell_meta(cmd))
198	        return 1;
199	
200	    /* Extract the first token (command name) */
201	    char first[64];
202	    int i = 0;
203	    while (cmd[i] == ' ') i++;
204	    int j = 0;
205	    while (cmd[i] && cmd[i] != ' ' && j < (int)sizeof(first) - 1)
206	        first[j++] = cmd[i++];
207	    first[j] = '\0';
208	
209	    /* Strip path prefix: /bin/rm -> rm, /usr/bin/dd -> dd */
210	    const char *basename = strrchr(first, '/');
211	    const char *name = basename ? basename + 1 : first;
212	
213	    /* VelaGuard: the agent may read board state, never change it. */
214	    for (int k = 0; s_vg_readonly[k].name; k++) {
215	        if (strcmp(name, s_vg_readonly[k].name) != 0)
216	            continue;
217	
218	        const char *want = s_vg_readonly[k].subcmd;
219	
220	        if (want == NULL)
221	            return 0;           /* read-only by construction */
222	
223	        if (want[0] == '\0')
224	            return 1;           /* nothing permitted, including bare name */
225	
226	        while (cmd[i] == ' ') i++;
227	        size_t wlen = strlen(want);
228	        if (strncmp(cmd + i, want, wlen) != 0)
229	            return 1;
230	        if (cmd[i + wlen] != '\0' && cmd[i + wlen] != ' ')
231	            return 1;           /* "dumpsters" must not pass as "dump" */
232	        return 0;
233	    }
234	
235	#ifdef CONFIG_VG_HMI
236	    /* Product shell tools only expose metadata. File operations use the
237	     * guarded file tools; general utilities could bypass their path policy. */
238	    static const char *metadata[] = {
239	        "free", "ps", "df", "uptime", "uname", "date", "heap_info",
240	        "net_status", "router_status", NULL
241	    };
242	    bool metadata_ok = false;
243	    for (int k = 0; metadata[k]; k++)
244	        if (!strcmp(name, metadata[k])) metadata_ok = true;
245	    if (!metadata_ok) return 1;
246	#endif
247	
248	    /* Check whitelist first */
249	    for (int k = 0; s_allowed[k]; k++) {
250	        if (strcmp(name, s_allowed[k]) == 0)
251	            return 0;  /* allowed */
252	    }
253	
254	    /* Then check blacklist */
255	    for (int k = 0; s_blocked[k]; k++) {
256	        if (strcmp(name, s_blocked[k]) == 0)
257	            return 1;  /* blocked */
258	    }
259	    
260	    /* Default deny in allowlist mode */
261	    return 1;
262	#endif
263	}
