265	/* Read a /proc file into buffer, return bytes read */
266	static size_t read_proc_file(const char *path, char *buf, size_t buf_size)
267	{
268	    FILE *fp = fopen(path, "r");
269	    if (!fp) return 0;
270	    size_t n = fread(buf, 1, buf_size - 1, fp);
271	    buf[n] = '\0';
272	    fclose(fp);
273	    return n;
274	}
