286	/* Built-in "ps" — read /proc/<pid>/status for each pid */
287	static int builtin_ps(char *output, size_t output_size)
288	{
289	    DIR *d = opendir("/proc");
290	    if (!d) return ERROR;
291	
292	    size_t off = 0;
293	    off = shell_append(output, output_size, off,
294	                    "%-6s %-4s %-8s %-20s %s\n",
295	                    "PID", "PRI", "STACK", "STATUS", "NAME");
296	
297	    struct dirent *ent;
298	    while ((ent = readdir(d)) != NULL && off < output_size && output_size - off > 128) {
299	        /* Only numeric dirs are PIDs */
300	        if (ent->d_name[0] < '0' || ent->d_name[0] > '9')
301	            continue;
302	
303	        char path[128];
304	        char buf[512] = {0};
305	
306	        snprintf(path, sizeof(path), "/proc/%.32s/status", ent->d_name);
307	        if (read_proc_file(path, buf, sizeof(buf)) > 0) {
308	            /* Trim trailing newline */
309	            char *nl = strchr(buf, '\n');
310	            if (nl) *nl = '\0';
311	            off = shell_append(output, output_size, off,
312	                            "%-6s %s\n", ent->d_name, buf);
313	        }
314	    }
315	    closedir(d);
316	    return OK;
317	}
