319	/* Built-in "df" — statfs on common mount points */
320	static int builtin_df(char *output, size_t output_size)
321	{
322	    static const char *mounts[] = { "/", "/tmp", "/data", NULL };
323	    size_t off = 0;
324	    off = shell_append(output, output_size, off,
325	                    "%-12s %12s %12s %12s\n",
326	                    "Filesystem", "Total", "Used", "Free");
327	
328	    for (int i = 0; mounts[i]; i++) {
329	        struct statfs sfs;
330	        if (statfs(mounts[i], &sfs) == 0) {
331	            unsigned long total = (unsigned long)sfs.f_blocks * sfs.f_bsize;
332	            unsigned long avail = (unsigned long)sfs.f_bavail * sfs.f_bsize;
333	            unsigned long used  = total - avail;
334	            off = shell_append(output, output_size, off,
335	                            "%-12s %10luKB %10luKB %10luKB\n",
336	                            mounts[i], total / 1024, used / 1024, avail / 1024);
337	        }
338	        if (off >= output_size - 1) break;
339	    }
340	    return OK;
341	}
