371	static bool is_path_allowed(const char *path)
372	{
373	    char resolved[PATH_MAX];
374	    /* Resolve symlinks to get the real path */
375	    if (realpath(path, resolved) == NULL) {
376	        /* If file doesn't exist, check the raw path */
377	        strncpy(resolved, path, sizeof(resolved) - 1);
378	        resolved[sizeof(resolved) - 1] = '\0';
379	    }
380	
381	    /* Normalise: strip trailing slash for comparison (except root "/") */
382	    size_t rlen = strlen(resolved);
383	    if (rlen > 1 && resolved[rlen - 1] == '/')
