420	static size_t list_dir_recursive(const char *dir_path, const char *prefix,
421	                                  char *output, size_t output_size, size_t off,
422	                                  int *count, int depth)
423	{
424	    if (output_size == 0 || off >= output_size - 1) return off;
425	    if (depth > 4) return off;  /* prevent infinite recursion */
426	
427	    DIR *dir = opendir(dir_path);
428	    if (!dir) return off;
429	
430	    struct dirent *ent;
431	    while ((ent = readdir(dir)) != NULL && off < output_size - 1) {
432	        /* Skip . and .. */
433	        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
434	            continue;
435	
436	        char full_path[512];
437	        snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, ent->d_name);
438	
439	        if (prefix && !path_has_prefix(full_path, prefix)) continue;
440	
441	        struct stat st;
442	        if (stat(full_path, &st) == 0 && S_ISDIR(st.st_mode)) {
443	            int n = snprintf(output + off, output_size - off, "%s/\n", full_path);
444	            if (n < 0 || (size_t)n >= output_size - off) {
445	                output[off] = 0;
446	                syslog(LOG_WARNING, "[%s] directory output truncated\n", TAG);
447	                break;
448	            }
449	            off += (size_t)n;
450	            (*count)++;
451	            off = list_dir_recursive(full_path, prefix, output, output_size, off, count, depth + 1);
452	        } else {
453	            int n = snprintf(output + off, output_size - off, "%s\n", full_path);
454	            if (n < 0 || (size_t)n >= output_size - off) {
455	                output[off] = 0;
456	                syslog(LOG_WARNING, "[%s] directory output truncated\n", TAG);
457	                break;
458	            }
459	            off += (size_t)n;
460	            (*count)++;
461	        }
462	    }
463	    closedir(dir);
464	    return off;
465	}
