    16	int agent_loop_ensure_started(void) { return 0; }
    17	int mbus_tap_register(const char *channel, mbus_tap_cb_t cb, void *cookie)
    18	{ (void)channel; tap = cb; tap_cookie = cookie; return 0; }
    19	void mbus_tap_unregister(const char *channel) { (void)channel; }
    20	int message_bus_push_inbound(const agent_msg_t *msg)
    21	{
    22	    if (fail_push) return -1;
    23	    sent = *msg;
    24	    free(sent.content);
    25	    sent.content = NULL;
    26	    return 0;
    27	}
    28	static void reply(int status, const char *text, void *cookie)
    29	{ assert(!status); assert(!strcmp(text, "reply")); assert(cookie == &calls); calls++; }
    30	
    31	int main(void)
    32	{
    33	    velaclaw_client_t *c = velaclaw_client_open("test");
    34	    velaclaw_ask_req_t req = {"test", 10};
    35	    assert(c);
    36	    assert(!velaclaw_ask(c, &req, reply, &calls));
    37	    agent_msg_t old = sent;
    38	    agent_msg_t progress = sent;
    39	    progress.content = "working";
    40	    progress.is_progress = true;
    41	    tap(&progress, tap_cookie);
    42	    assert(calls == 0);
    43	    assert(velaclaw_ask(c, &req, reply, &calls) == -EBUSY);
    44	    usleep(20000);
    45	    assert(!velaclaw_ask(c, &req, reply, &calls));
    46	    agent_msg_t current = sent;
    47	    old.content = "reply";
    48	    tap(&old, tap_cookie);
    49	    assert(calls == 0);
    50	    current.content = "reply";
    51	    tap(&current, tap_cookie);
    52	    assert(calls == 1);
    53	    tap(&current, tap_cookie);
    54	    assert(calls == 1);
    55	    fail_push = 1;
    56	    assert(velaclaw_ask(c, &req, reply, &calls) < 0);
    57	    fail_push = 0;
    58	    assert(!velaclaw_ask(c, &req, reply, &calls));
    59	    current = sent;
    60	    current.content = "reply";
    61	    tap(&current, tap_cookie);
    62	    assert(calls == 2);
    63	    velaclaw_client_close(c);
    64	    puts("test_local_client: OK (busy, stale, duplicate, failed submit, recovery)");
    65	    return 0;
    66	}
