1	/*
2	 * velaclaw_client_local.c - Flat-build local IPC client for ai_agent
3	 *
4	 * Uses direct function calls to message_bus (shared address space)
5	 * and mbus_tap to intercept outbound replies synchronously.
6	 */
7	
8	#include <velaclaw/client.h>
9	
10	#include <errno.h>
11	#include <pthread.h>
12	#include <semaphore.h>
13	#include <stdlib.h>
14	#include <string.h>
15	#include <syslog.h>
16	#include <stdio.h>
17	#include <time.h>
18	
19	#include "core/agent_loop.h"
20	#include "core/message_bus.h"
21	#include "core/message_bus_tap.h"
22	
23	#define TAG "velaclaw_client"
24	#define CLIENT_CHANNEL "local_client"
25	
26	struct velaclaw_client_s {
27	    char app_id[32];
28	    pthread_mutex_t mtx;
29	    sem_t reply_sem;
30	    char* reply_text;
31	    int reply_status;
32	    void (*async_cb)(int, const char*, void*);
33	    void* async_cookie;
34	    char pending_id[64];
35	    uint32_t serial;
36	    uint32_t started_ms;
37	    uint32_t timeout_ms;
38	    bool active;
39	};
40	
41	static struct velaclaw_client_s* g_client_instance;
42	
43	static uint32_t client_now_ms(void)
44	{
45	    struct timespec ts;
46	    clock_gettime(CLOCK_MONOTONIC, &ts);
47	    return (uint32_t)((uint64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
48	}
49	
50	static void tap_callback(const agent_msg_t* msg, void* cookie)
51	{
52	    struct velaclaw_client_s* c = cookie;
53	    if (!c || !msg || msg->is_progress) return;
54	    pthread_mutex_lock(&c->mtx);
55	    /* An old round can reply after its caller timed out and submitted a new
56	     * one. Correlate the bus reply, not just the current callback slot. */
57	    if (!c->active || strcmp(msg->chat_id, c->pending_id) != 0) {
58	        pthread_mutex_unlock(&c->mtx);
59	        return;
60	    }
61	    void (*cb)(int, const char*, void*) = c->async_cb;
62	    void* ck = c->async_cookie;
63	    bool expired = client_now_ms() - c->started_ms >= c->timeout_ms;
64	    c->active = false;
65	    c->async_cb = NULL;
66	    c->async_cookie = NULL;
67	    pthread_mutex_unlock(&c->mtx);
68	    if (cb && !expired) cb(0, msg->content, ck);
69	}
70	
71	velaclaw_client_t* velaclaw_client_open(const char* name)
72	{
73	    if (g_client_instance) {
74	        return g_client_instance;
75	    }
76	
77	    struct velaclaw_client_s* c = calloc(1, sizeof(*c));
78	    if (!c) {
79	        return NULL;
80	    }
81	
82	    strncpy(c->app_id, name ? name : "app", sizeof(c->app_id) - 1);
83	    pthread_mutex_init(&c->mtx, NULL);
84	    sem_init(&c->reply_sem, 0, 0);
85	    c->reply_text = NULL;
86	    c->reply_status = 0;
87	
88	    if (mbus_tap_register(CLIENT_CHANNEL, tap_callback, c) != OK) {
89	        syslog(LOG_ERR, "[%s] tap register failed (agent not running?)\n", TAG);
90	        sem_destroy(&c->reply_sem);
91	        pthread_mutex_destroy(&c->mtx);
92	        free(c);
93	        return NULL;
94	    }
95	
96	    g_client_instance = c;
97	    syslog(LOG_INFO, "[%s] client opened: %s\n", TAG, c->app_id);
98	    return c;
99	}
100	
101	void velaclaw_client_close(velaclaw_client_t* c)
102	{
103	    if (!c) {
104	        return;
105	    }
106	
107	    mbus_tap_unregister(CLIENT_CHANNEL);
108	
109	    pthread_mutex_destroy(&c->mtx);
110	    sem_destroy(&c->reply_sem);
111	    free(c->reply_text);
112	    c->reply_text = NULL;
113	
114	    if (g_client_instance == c) {
115	        g_client_instance = NULL;
116	    }
117	
118	    free(c);
119	    syslog(LOG_INFO, "[%s] client closed\n", TAG);
120	}
121	
122	int velaclaw_ask_async(velaclaw_client_t* c,
123	    const velaclaw_ask_req_t* req,
124	    void (*cb)(int, const char*, void*), void* cookie)
125	{
126	    if (!c || !req || !req->text) {
127	        return -EINVAL;
128	    }
129	
130	    /* Under CONFIG_VG_HMI this only raises the start request; the network
131	     * watcher spins the loop up within about a second.  Other builds start
132	     * it outright.  Either way, ask before the message is queued so the
133	     * consumer exists by the time it lands. */
134	    agent_loop_ensure_started();
135	
136	    return velaclaw_ask(c, req, cb, cookie);
137	}
138	
139	int velaclaw_ask(velaclaw_client_t* c,
140	    const velaclaw_ask_req_t* req,
141	    void (*cb)(int, const char*, void*), void* cookie)
142	{
143	    if (!c || !req || !req->text) {
144	        return -EINVAL;
145	    }
146	
147	    agent_msg_t msg = {0};
148	    msg.content = strdup(req->text);
149	    if (!msg.content) return -ENOMEM;
150	    pthread_mutex_lock(&c->mtx);
151	    uint32_t now = client_now_ms();
152	    if (c->active && now - c->started_ms < c->timeout_ms) {
153	        pthread_mutex_unlock(&c->mtx);
154	        free(msg.content);
155	        return -EBUSY;
156	    }
157	    c->serial++;
158	    snprintf(c->pending_id, sizeof(c->pending_id), "%s:%u",
159	             c->app_id, (unsigned)c->serial);
160	    c->started_ms = now;
161	    c->timeout_ms = req->timeout_ms > 0 ? (uint32_t)req->timeout_ms : 300000u;
162	    c->active = true;
163	    c->async_cb = cb;
164	    c->async_cookie = cookie;
165	    strcpy(msg.channel, CLIENT_CHANNEL);
166	    strcpy(msg.chat_id, c->pending_id);
167	    pthread_mutex_unlock(&c->mtx);
168	
169	    int ret = message_bus_push_inbound(&msg);
170	    if (ret != OK) {
171	        free(msg.content);
172	        pthread_mutex_lock(&c->mtx);
173	        if (!strcmp(c->pending_id, msg.chat_id)) {
174	            c->active = false;
175	            c->async_cb = NULL;
176	            c->async_cookie = NULL;
177	        }
178	        pthread_mutex_unlock(&c->mtx);
179	        return -EIO;
180	    }
181	    return 0;
182	}
