1	/****************************************************************************
2	 * app/velaguard/vg_agent_round.c
3	 ****************************************************************************/
4	
5	#include <nuttx/config.h>
6	
7	#ifdef CONFIG_EXAMPLES_AI_AGENT_VELA
8	
9	#include <errno.h>
10	#include <pthread.h>
11	#include <string.h>
12	#include <syslog.h>
13	#include <time.h>
14	
15	#include <velaclaw/client.h>
16	
17	#include "vg_agent_round.h"
18	
19	#define TAG "vgagent"
20	
21	#define VG_ROUND_REQ_MAX   1536
22	#define VG_ROUND_REPLY_MAX 192
23	
24	static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;
25	
26	static velaclaw_client_t          *g_client;
27	static enum vg_agent_round_state   g_state = VG_AGENT_ROUND_IDLE;
28	static uint32_t                    g_started_ms;
29	static uint32_t                    g_generation;
30	static uint32_t                    g_request_serial;
31	static bool                        g_reply_seen;
32	static bool                        g_reply_ok;
33	static bool                        g_submitting;
34	static enum vg_agent_round_owner   g_owner;
35	static uint32_t                    g_finished_ms;
36	
37	static char g_req[VG_ROUND_REQ_MAX];
38	static char g_reply[VG_ROUND_REPLY_MAX];
39	
40	uint32_t vg_agent_round_now_ms(void)
41	{
42	  struct timespec ts;
43	
44	  (void)clock_gettime(CLOCK_MONOTONIC, &ts);
45	  return (uint32_t)((uint64_t)ts.tv_sec * 1000u
46	                    + (uint64_t)ts.tv_nsec / 1000000u);
47	}
48	
49	/* Runs on the agent's outbound dispatch thread, so it only records the
50	 * outcome and never blocks on anything but this mutex. */
51	
52	static void round_reply(int status, const char *text, void *cookie)
53	{
54	  pthread_mutex_lock(&g_lock);
55	  if ((uint32_t)(uintptr_t)cookie != g_request_serial ||
56	      (g_state != VG_AGENT_ROUND_QUEUED && g_state != VG_AGENT_ROUND_RUNNING))
57	    { pthread_mutex_unlock(&g_lock); return; }
58	  g_reply_seen = true;
59	  g_reply_ok = (status == 0);
60	
61	  if (text != NULL)
62	    {
63	      strncpy(g_reply, text, sizeof(g_reply) - 1);
64	      g_reply[sizeof(g_reply) - 1] = '\0';
65	    }
66	  else
67	    {
68	      g_reply[0] = '\0';
69	    }
70	
71	  pthread_mutex_unlock(&g_lock);
72	}
73	
74	int vg_agent_round_init(void)
75	{
76	  int rc = 0;
77	
78	  pthread_mutex_lock(&g_lock);
79	
80	  if (g_client == NULL)
81	    {
82	      /* Fails while the agent's message bus is still coming up; the worker
83	       * retries on later ticks until VG_AGENT_ROUND_QUEUE_TIMEOUT_MS. */
84	
85	      g_client = velaclaw_client_open("velaguard");
86	      if (g_client != NULL)
87	        {
88	          syslog(LOG_INFO, "[%s] local agent client ready\n", TAG);
89	        }
90	    }
91	
92	  if (g_client == NULL)
93	    {
94	      rc = -ENODEV;
95	    }
96	
97	  pthread_mutex_unlock(&g_lock);
98	  return rc;
99	}
100	
101	int vg_agent_round_queue(const char *text)
102	{
103	  return vg_agent_round_queue_owned(text, VG_AGENT_ROUND_OWNER_NONE);
104	}
105	
106	int vg_agent_round_queue_owned(const char *text,
107	                               enum vg_agent_round_owner owner)
108	{
109	  size_t len;
110	
111	  if (text == NULL)
112	    {
113	      return -EINVAL;
114	    }
115	
116	  len = strlen(text);
117	  if (len == 0)
118	    {
119	      return -EINVAL;
120	    }
121	
122	  if (len >= VG_ROUND_REQ_MAX)
123	    {
124	      return -E2BIG;
125	    }
126	
127	  pthread_mutex_lock(&g_lock);
128	
129	  /* A finished result that its owner has not read yet is not free: letting
130	   * another flow overwrite it would discard an artifact that is already on
131	   * eMMC.  Both consumers clear their own result within a tick, so this only
132	   * ever costs the new request one worker iteration. */
133	
134	  if (g_state != VG_AGENT_ROUND_IDLE)
135	    {
136	      pthread_mutex_unlock(&g_lock);
137	      return -EBUSY;
138	    }
139	
140	  if (++g_request_serial == 0) ++g_request_serial;
141	  memcpy(g_req, text, len + 1);
142	  g_owner = owner;
143	  g_state = VG_AGENT_ROUND_QUEUED;
144	  g_started_ms = vg_agent_round_now_ms();
145	  g_reply_seen = false;
146	  g_reply_ok = false;
147	  g_reply[0] = '\0';
148	
149	  pthread_mutex_unlock(&g_lock);
150	  return 0;
151	}
152	
153	static void round_submit(void)
154	{
155	  /* Function-local so a 1.5 KB request never lands on the worker stack, and
156	   * released before the call so the reply callback can never contend with us
157	   * on the same lock if a build ever dispatches replies synchronously. */
158	
159	  static char req[VG_ROUND_REQ_MAX];
160	  velaclaw_client_t *client;
161	  velaclaw_ask_req_t ask;
162	  int rc;
163	  uint32_t serial;
164	
165	  pthread_mutex_lock(&g_lock);
166	  if (g_client == NULL)
167	    {
168	      pthread_mutex_unlock(&g_lock);
169	
170	      if (vg_agent_round_init() != 0)
171	        {
172	          return;
173	        }
174	
175	      pthread_mutex_lock(&g_lock);
176	    }
177	
178	  client = g_client;
179	  memcpy(req, g_req, sizeof(req));
180	  serial = g_request_serial;
181	  pthread_mutex_unlock(&g_lock);
182	
183	  ask.text = req;
184	  ask.timeout_ms = (int)VG_AGENT_ROUND_TIMEOUT_MS;
185	
186	  rc = velaclaw_ask_async(client, &ask, round_reply, (void *)(uintptr_t)serial);
187	
188	  pthread_mutex_lock(&g_lock);
189	  if (rc == 0)
190	    {
191	      g_state = VG_AGENT_ROUND_RUNNING;
192	      g_started_ms = vg_agent_round_now_ms();
193	      syslog(LOG_INFO, "[%s] round submitted: %u bytes\n",
194	             TAG, (unsigned)strlen(req));
195	    }
196	  else
197	    {
198	      g_state = VG_AGENT_ROUND_ERROR;
199	      g_finished_ms = vg_agent_round_now_ms();
200	      syslog(LOG_WARNING, "[%s] round submit failed: %d\n", TAG, rc);
201	    }
202	
203	  pthread_mutex_unlock(&g_lock);
204	}
205	
206	void vg_agent_round_tick(void)
207	{
208	  pthread_mutex_lock(&g_lock);
209	  if (g_state == VG_AGENT_ROUND_QUEUED)
210	    {
211	      if (g_submitting) { pthread_mutex_unlock(&g_lock); return; }
212	      g_submitting = true;
213	      pthread_mutex_unlock(&g_lock);
214	      round_submit();
215	      pthread_mutex_lock(&g_lock);
216	      g_submitting = false;
217	      if (g_state == VG_AGENT_ROUND_QUEUED &&
218	          (int32_t)(vg_agent_round_now_ms() - g_started_ms) >=
219	          (int32_t)VG_AGENT_ROUND_QUEUE_TIMEOUT_MS)
220	        {
221	          g_state = VG_AGENT_ROUND_ERROR;
222	          g_finished_ms = vg_agent_round_now_ms();
223	          syslog(LOG_WARNING, "[%s] round never reached the agent\n", TAG);
224	        }
225	      pthread_mutex_unlock(&g_lock);
226	      return;
227	    }
228	  if (g_state != VG_AGENT_ROUND_RUNNING)
229	    { pthread_mutex_unlock(&g_lock); return; }
230	
231	  uint32_t now = vg_agent_round_now_ms();
232	  if (g_reply_seen)
233	    {
234	      bool ok = g_reply_ok;
235	      g_reply_seen = false;
236	      g_state = ok ? VG_AGENT_ROUND_DONE : VG_AGENT_ROUND_ERROR;
237	      if (ok) g_generation++;
238	      g_finished_ms = now;
239	      pthread_mutex_unlock(&g_lock);
240	      syslog(LOG_INFO, "[%s] round finished: %s\n", TAG, ok ? "reply" : "agent error");
