246	      g_finished_ms = now;
247	      pthread_mutex_unlock(&g_lock);
248	      syslog(LOG_WARNING, "[%s] round timed out\n", TAG);
249	      return;
250	    }
251	  pthread_mutex_unlock(&g_lock);
