291	bool vg_agent_round_reclaim(enum vg_agent_round_owner mine, uint32_t grace_ms)
292	{
293	  bool released = false;
294	
295	  pthread_mutex_lock(&g_lock);
296	
297	  if ((g_state == VG_AGENT_ROUND_DONE || g_state == VG_AGENT_ROUND_ERROR) &&
298	      g_owner != mine && g_finished_ms != 0 &&
299	      vg_agent_round_now_ms() - g_finished_ms >= grace_ms)
300	    {
301	      /* Somebody else's finished round that nobody is going to read - a
302	       * manual round killed half way, or a flow that went away.  Without
303	       * this the strict queue would hold the channel for it forever. */
304	
305	      g_state = VG_AGENT_ROUND_IDLE;
306	      g_owner = VG_AGENT_ROUND_OWNER_NONE;
307	      released = true;
308	    }
309	
310	  pthread_mutex_unlock(&g_lock);
311	  return released;
312	}
