2	 * app/velaguard/vg_agent_tools.c
3	 *
4	 * Two read-only tools for the on-board agent, registered through the
5	 * ai_agent provider hook (packages/ai_agent include/tools/tool_provider.h):
6	 *
7	 *   vg_point_read {query?}  live value from the confirmed point table
8	 *   vg_run_report {}        since-boot report, same text as the report page
9	 *
10	 * Neither opens RS485.  vg_point_read reads the HMI poll snapshot and the
11	 * committed table, exactly what NSH `vgpoint get` does and what
12	 * docs/velaguard-host-nsh-protocol.md requires of it: taking the bus lock
13	 * here would stall the poller behind an LLM round that can last minutes.
14	 ****************************************************************************/
15	
16	#include <nuttx/config.h>
17	
18	#ifdef CONFIG_EXAMPLES_AI_AGENT_VELA
19	
20	/* Each tool depends on a VelaGuard module that not every target builds.
21	 * velaguard-ai-probe, for instance, enables ai_agent without the frame-stat
22	 * or point-table modules, so a tool whose data source is absent must not be
23	 * advertised: the model would call it and get a link error instead of data. */
24	
