83	/* Build the agent-facing view of the confirmed table.  Returns 0 when values
84	 * are available, or a vg_agent_query_rc reason otherwise.  Values come from
85	 * the live snapshot, which is written with tmp+rename so a reader never sees
86	 * a torn file. */
87	
88	static enum vg_agent_query_rc collect_points(struct vg_agent_point *out,
89	                                             int *n_out)
90	{
91	  struct vg_discover_summary table;
92	  struct vg_live_snapshot snap;
93	  bool have_snap = false;
94	  enum vg_agent_query_rc rc = VG_AGENT_QUERY_OK;
95	  uint32_t age = 0;
96	  int i;
97	  int rc_read;
98	
99	  if (out == NULL || n_out == NULL)
100	    {
101	      return VG_AGENT_QUERY_ARG;
102	    }
103	
104	  *n_out = 0;
105	  rc_read = vg_point_table_read(&table, CONFIG_VG_DISCOVER_POINTS_PATH);
106	
107	  if (rc_read == -ENOENT)
108	    {
109	      /* An absent table is empty only while the store itself is reachable.
110	       * When /data is gone the honest answer is "cannot read", not "no
111	       * points configured": the two look identical otherwise, and the NSH
112	       * tools separate them the same way (vgpoint.c cmd_get). */
113	      if (vg_point_store_root_ok(CONFIG_VG_STORE_ROOT) == 0)
114	        {
115	          memset(&table, 0, sizeof(table));
116	          rc_read = 0;
117	        }
118	    }
119	
120	  if (rc_read != 0 || table.n_points <= 0)
121	    {
122	      return VG_AGENT_QUERY_NO_TABLE;
123	    }
124	
125	  if (vg_live_snapshot_read(CONFIG_VG_LIVE_VALUES_PATH, &snap) == 0)
126	    {
127	      have_snap = true;
128	      age = vg_live_age_ms(snap.tick_ms, vg_live_now_ms());
129	    }
130	
131	  for (i = 0; i < table.n_points && i < VG_AGENT_QUERY_MAX; i++)
132	    {
133	      const struct vg_point_entry *e = &table.points[i];
134	      struct vg_agent_point *p = &out[i];
135	      int idx;
136	
137	      memset(p, 0, sizeof(*p));
138	      snprintf(p->id, sizeof(p->id), "%s", e->id);
139	      snprintf(p->name, sizeof(p->name), "%s",
140	               e->name[0] ? e->name : e->id);
141	      snprintf(p->unit, sizeof(p->unit), "%s", e->unit);
142	      snprintf(p->cmp, sizeof(p->cmp), "%s", e->cmp);
143	      p->has_warn = e->has_warn != 0;
144	      p->warn = e->warn;
145	      p->has_crit = e->has_crit != 0;
146	      p->crit = e->crit;
147	
148	      if (!have_snap)
149	        {
150	          continue;
151	        }
152	
153	      idx = vg_live_snapshot_find_id(&snap, e->id);
154	      if (idx < 0)
155	        {
156	          continue;
157	        }
158	
159	      p->has_sample = true;
160	      p->ok = snap.samples[idx].ok != 0;
161	      p->value = snap.samples[idx].value;
162	      p->age_ms = age;
163	    }
164	
165	  if (!have_snap)
166	    {
167	      /* The table is known but nothing has been sampled yet.  Report the
168	       * thresholds without inventing values. */
169	      rc = VG_AGENT_QUERY_NO_SAMPLE;
170	    }
171	
172	  *n_out = (table.n_points < VG_AGENT_QUERY_MAX)
173	               ? table.n_points
174	               : VG_AGENT_QUERY_MAX;
175	  return rc;
176	}
