178	static int tool_point_read(const char *query, char *out, size_t cap)
179	{
180	  struct vg_agent_point points[VG_AGENT_QUERY_MAX];
181	  struct vg_agent_query_result res;
182	  enum vg_agent_query_rc collect_rc;
183	  enum vg_agent_query_rc rc;
184	  int n = 0;
185	
186	  collect_rc = collect_points(points, &n);
187	
188	  if (collect_rc == VG_AGENT_QUERY_NO_TABLE)
189	    {
190	      snprintf(out, cap,
191	               "vgquery: reason=no_table msg=已确认点表不可读或尚未导入\n");
192	      return OK;
193	    }
194	
195	  if (n <= 0)
196	    {
197	      snprintf(out, cap, "vgquery: reason=no_table msg=已确认点表为空\n");
198	      return OK;
199	    }
200	
201	  rc = vg_agent_query_match(points, n, query, &res);
202	
203	  switch (rc)
204	    {
205	      case VG_AGENT_QUERY_OK:
206	        vg_agent_query_format_point(out, cap, &points[res.index],
207	                                    vg_agent_query_is_stale(
208	                                        &points[res.index]));
209	        break;
210	
211	      case VG_AGENT_QUERY_AMBIG:
212	        vg_agent_query_format_candidates(out, cap, points, n, &res);
213	        break;
214	
215	      case VG_AGENT_QUERY_NOT_FOUND:
216	        vg_agent_query_format_list(out, cap, points, n);
217	        snprintf(out + strlen(out), cap - strlen(out),
218	                 "vgquery: reason=not_found query=%s\n",
219	                 (query != NULL) ? query : "");
220	        break;
221	
222	      case VG_AGENT_QUERY_LIST:
223	      default:
224	        vg_agent_query_format_list(out, cap, points, n);
225	        break;
226	    }
227	
228	  /* Reaching here means the question was answered, including "no sample
229	   * yet": that is a real answer, and the text says where the data is
230	   * missing.  Only an unreadable table takes the early return above. */
231	  return OK;
232	}
