280	static size_t app_str(char *buf, size_t cap, size_t off, const char *s)
281	{
282	  size_t n;
283	
284	  if (buf == NULL || cap == 0 || s == NULL || off >= cap - 1)
285	    {
286	      return off;
287	    }
288	
289	  n = strlen(s);
290	  if (n > cap - 1 - off)
291	    {
292	      n = cap - 1 - off;
293	    }
294	
295	  memcpy(buf + off, s, n);
296	  buf[off + n] = '\0';
297	  return off + n;
298	}
