300	static char *vg_tools_get_json(void)
301	{
302	  char buf[2048];
303	  size_t off = 0;
304	
305	  buf[0] = '\0';
306	  off = app_str(buf, sizeof(buf), off, "[");
307	
308	  /* The comma is chosen at compile time because the set of tools is fixed
309	   * then; a runtime "is this the first entry" flag would be dead code in
310	   * every single-tool build. */
311	
312	#ifdef VG_AGENT_TOOLS_HAVE_POINTS
313	  off = app_str(buf, sizeof(buf), off, VG_TOOL_POINT_JSON);
314	#endif
315	
316	#ifdef VG_AGENT_TOOLS_HAVE_REPORT
317	#  ifdef VG_AGENT_TOOLS_HAVE_POINTS
318	  off = app_str(buf, sizeof(buf), off, ",");
319	#  endif
320	
321	  off = app_str(buf, sizeof(buf), off, VG_TOOL_REPORT_JSON);
322	#endif
323	
324	  (void)app_str(buf, sizeof(buf), off, "]");
325	
326	  return strdup(buf);
327	}
