329	/* Extract the optional query string and bound it.  Returns 0 on success and
330	 * leaves *query NULL when the caller omitted it.  Only vg_point_read takes an
331	 * argument, so this lives inside that tool's build guard. */
332	
333	#ifdef VG_AGENT_TOOLS_HAVE_POINTS
334	static int parse_query(const char *input_json, char *buf, size_t cap,
335	                       const char **query)
336	{
337	  cJSON *root;
338	  cJSON *item;
339	  const char *s;
340	  size_t len;
341	
342	  *query = NULL;
343	
344	  if (input_json == NULL || input_json[0] == '\0')
345	    {
346	      return 0;
347	    }
348	
349	  root = cJSON_Parse(input_json);
350	  if (root == NULL)
351	    {
352	      return -EINVAL;
353	    }
354	
355	  item = cJSON_GetObjectItem(root, "query");
356	  if (item == NULL || cJSON_IsNull(item))
357	    {
358	      cJSON_Delete(root);
359	      return 0;
360	    }
361	
362	  if (!cJSON_IsString(item))
363	    {
364	      cJSON_Delete(root);
365	      return -EINVAL;
366	    }
367	
368	  s = item->valuestring;
369	  len = strlen(s);
370	
371	  if (len >= cap)
372	    {
373	      /* Reject rather than truncate: a cut point name could match a
374	       * different point and answer the wrong question. */
375	      cJSON_Delete(root);
376	      return -E2BIG;
377	    }
378	
379	  memcpy(buf, s, len + 1);
380	  *query = buf;
381	  cJSON_Delete(root);
382	  return 0;
383	}
384	#endif /* VG_AGENT_TOOLS_HAVE_POINTS */
