386	/* ── call rate ───────────────────────────────────────────────────────
387	 *
388	 * tool_guard.c rate-limits run_shell / write_file / edit_file only, so a
389	 * read-only tool has no ceiling there.  AGENTS.md requires the limit to live
390	 * in C rather than the prompt, and an unthrottled read is still an eMMC read
391	 * on every iteration, so cap it here.  The ReAct loop already bounds a round
392	 * (10 iterations, 4 same-name repeats); this bounds the burst inside it.
393	 * The rule itself lives in vg_agent_query.c so host tests can drive it.
394	 */
395	
396	#define VG_TOOL_RATE_WINDOW_MS 60000u
397	#define VG_TOOL_RATE_MAX_CALLS 20
398	
399	static struct vg_agent_rate g_rate;
400	
401	static uint32_t rate_now_ms(void)
402	{
403	  struct timespec ts;
404	
405	  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
406	    {
407	      return 0;
408	    }
409	
410	  return (uint32_t)((uint64_t)ts.tv_sec * 1000u
411	                    + (uint64_t)ts.tv_nsec / 1000000u);
412	}
413	
414	static int vg_tools_execute(const char *name, const char *input_json,
415	                            char *output, size_t output_size)
416	{
417	  size_t cap;
418	
419	  /* input_json is only read by vg_point_read; the report tool takes none. */
420	  (void)input_json;
421	
422	  if (name == NULL || output == NULL || output_size == 0)
423	    {
424	      return ERROR;
425	    }
426	
427	  cap = (output_size > VG_AGENT_TOOL_OUT_MAX)
428	            ? VG_AGENT_TOOL_OUT_MAX
429	            : output_size;
430	
431	  output[0] = '\0';
432	
433	  /* Only count calls we actually own, so a probe for someone else's tool does
434	   * not spend this provider's budget, and a tool this build did not compile
435	   * in is not claimed at all. */
436	  {
437	    bool owned = false;
438	
439	#ifdef VG_AGENT_TOOLS_HAVE_POINTS
440	    if (strcmp(name, "vg_point_read") == 0)
441	      {
442	        owned = true;
443	      }
444	#endif
445	
446	#ifdef VG_AGENT_TOOLS_HAVE_REPORT
447	    if (strcmp(name, "vg_run_report") == 0)
448	      {
449	        owned = true;
450	      }
451	#endif
452	
453	    if (!owned)
454	      {
455	        return ERROR;
456	      }
457	  }
458	
459	  if (!vg_agent_rate_allow(&g_rate, rate_now_ms()))
460	    {
461	      /* OK, not ERROR: the registry reads a provider's ERROR as "not my
462	       * tool", skips to the next provider and finally overwrites this buffer
463	       * with "unknown tool".  A rate-limited call would then reach the model
464	       * as a tool that does not exist, and it would keep retrying instead of
465	       * waiting.  Only a name we do not own may return ERROR. */
466	      snprintf(output, cap,
467	               "vgquery: reason=rate_limited msg=调用过于频繁，请稍后再试\n");
468	      return OK;
469	    }
470	
471	#ifdef VG_AGENT_TOOLS_HAVE_POINTS
472	  if (strcmp(name, "vg_point_read") == 0)
473	    {
474	      char query[VG_AGENT_TOOL_QUERY_MAX];
475	      const char *q = NULL;
476	      int rc;
477	
478	      rc = parse_query(input_json, query, sizeof(query), &q);
479	
480	      if (rc == -E2BIG)
481	        {
482	          snprintf(output, cap,
483	                   "vgquery: reason=bad_arg msg=query 过长，上限 %d 字节\n",
484	                   VG_AGENT_TOOL_QUERY_MAX - 1);
485	          return OK;
486	        }
487	
488	      if (rc != 0)
489	        {
490	          snprintf(output, cap,
491	                   "vgquery: reason=bad_arg msg=query 必须是字符串\n");
492	          return OK;
493	        }
494	
495	      return tool_point_read(q, output, cap);
496	    }
497	#endif
498	
499	#ifdef VG_AGENT_TOOLS_HAVE_REPORT
500	  if (strcmp(name, "vg_run_report") == 0)
501	    {
502	      return tool_run_report(output, cap);
503	    }
504	#endif
505	
506	  /* Not ours: let the registry try the next provider. */
507	  return ERROR;
508	}
509	
510	#endif /* any tool */
