/****************************************************************************
 * host_tests/agent_review/test_runner_budget.c
 *
 * Fault injection for the bounded shell runner (tool_shell_runner.c).
 *
 * The ai_agent tree already ships tests/test_shell_runner.c, which covers the
 * happy path, a silent hang, a child that closes stdout, a bounded overflow,
 * recovery and the direct-child reap.  This file adds only what that one
 * cannot show:
 *
 *   1. a child that never stops producing output still hits the deadline
 *      (the drain loop must not be starved by the read side);
 *   2. the deadline is honoured to within a bounded error, so a stuck
 *      command cannot hold the tool thread for an unbounded time;
 *   3. a background descendant of the command is reclaimed, not left
 *      running behind a returned timeout  (host: process-group kill);
 *   4. repeated timeouts leak neither file descriptors nor children;
 *   5. a child killed by a signal is a failure, not a success;
 *   6. the output buffer is written only inside [0, cap-1], for caps of
 *      1, 2, 3, 5, 64 and 257 bytes;
 *   7. the documented argument guards actually reject.
 *
 * Every command is bounded: the longest single run is about 1.2 s.
 ****************************************************************************/

#include "tools/tool_shell_runner.h"

#include <assert.h>
#include <dirent.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

static uint64_t mono_ms(void)
{
    struct timespec ts;
    assert(clock_gettime(CLOCK_MONOTONIC, &ts) == 0);
    return (uint64_t)ts.tv_sec * 1000u + (uint64_t)ts.tv_nsec / 1000000u;
}

/* Count of open descriptors, used only for a before/after comparison. */
static int open_fds(void)
{
    DIR *d = opendir("/proc/self/fd");
    struct dirent *e;
    int n = 0;
    assert(d != NULL);
    while ((e = readdir(d)) != NULL)
        if (e->d_name[0] != '.')
            n++;
    closedir(d);
    return n;
}

/* 1 + 2: a command that never stops writing must still end at the deadline. */
static void test_endless_output_hits_deadline(void)
{
    char out[64];
    uint64_t t0 = mono_ms();
    int rc = tool_shell_run("while true; do printf x; done", out, sizeof(out), 200);
    uint64_t elapsed = mono_ms() - t0;

    assert(rc == -ETIMEDOUT);
    assert(elapsed >= 180);    /* must not give up before the budget */
    assert(elapsed <= 1200);   /* and must not run past it */
    assert(strlen(out) == sizeof(out) - 1);   /* capped and terminated */
}

/* 2: the deadline for a silent hang is the requested one, not "eventually". */
static void test_deadline_is_accurate(void)
{
    char out[64];
    uint64_t t0 = mono_ms();
    int rc = tool_shell_run("sleep 5", out, sizeof(out), 300);
    uint64_t elapsed = mono_ms() - t0;

    assert(rc == -ETIMEDOUT);
    assert(elapsed >= 280);
    assert(elapsed <= 1200);
}

/* 3: what the command left behind in the background must be gone.
 *
 * The child is started as its own process-group leader, so on the host the
 * kill reaches everything it forked.  NuttX only signals the task itself
 * (kill(pid, SIGKILL), no group), which is why this property is a host
 * result and not a board result - see the review document.
 */
static void test_background_descendant_is_reclaimed(void)
{
    char dir[] = "/tmp/vg-runner-reclaim-XXXXXX";
    char marker[256];
    char cmd[512];
    char out[64];

    assert(mkdtemp(dir) != NULL);
    snprintf(marker, sizeof(marker), "%s/marker", dir);
    snprintf(cmd, sizeof(cmd),
             "(sleep 0.5; printf late > %s) & sleep 5", marker);

    assert(tool_shell_run(cmd, out, sizeof(out), 50) == -ETIMEDOUT);

    /* Wait well past the point where the background writer would have run. */
    usleep(900000);
    assert(access(marker, F_OK) != 0);

    unlink(marker);
    rmdir(dir);
}

/* 4: the stop path must give the descriptors back and reap the child. */
static void test_repeated_timeouts_do_not_leak(void)
{
    char out[64];
    int before = open_fds();
    int i;

    for (i = 0; i < 30; i++)
        assert(tool_shell_run("sleep 5", out, sizeof(out), 20) == -ETIMEDOUT);

    assert(open_fds() <= before + 1);

    /* No child of ours may be left unreaped. */
    assert(waitpid(-1, NULL, WNOHANG) < 0 && errno == ECHILD);

    /* And the next normal request still works. */
    assert(tool_shell_run("printf recovered", out, sizeof(out), 500) == 0);
    assert(!strcmp(out, "recovered"));
}

/* 5: a signalled child is a failure, not an empty success. */
static void test_signalled_child_is_a_failure(void)
{
    char out[64];
    assert(tool_shell_run("kill -9 $$", out, sizeof(out), 500) == -EIO);
    assert(tool_shell_run("", out, sizeof(out), 200) == 0);
    assert(out[0] == '\0');
}

/* 6: exact canaries for tiny and awkward caps. */
static void test_output_stays_inside_the_cap(void)
{
    static const size_t caps[] = { 1, 2, 3, 5, 64, 257 };
    unsigned char raw[300];
    size_t i;

    for (i = 0; i < sizeof(caps) / sizeof(caps[0]); i++)
    {
        size_t cap = caps[i];
        size_t j;

        memset(raw, 0xa5, sizeof(raw));
        (void)tool_shell_run("printf abcdefghij", (char *)raw + 1, cap, 500);
        assert(raw[0] == 0xa5);
        for (j = cap + 1; j < sizeof(raw); j++)
            assert(raw[j] == 0xa5);
    }
}

/* 7: the argument guards documented in the header. */
static void test_argument_guards(void)
{
    char out[32];
    assert(tool_shell_run(NULL, out, sizeof(out), 100) == -EINVAL);
    assert(tool_shell_run("x", NULL, sizeof(out), 100) == -EINVAL);
    assert(tool_shell_run("x", out, 0, 100) == -EINVAL);
    assert(tool_shell_run("x", out, sizeof(out), 0) == -EINVAL);
}

int main(void)
{
    test_argument_guards();
    test_endless_output_hits_deadline();
    test_deadline_is_accurate();
    test_background_descendant_is_reclaimed();
    test_repeated_timeouts_do_not_leak();
    test_signalled_child_is_a_failure();
    test_output_stays_inside_the_cap();

    puts("test_runner_budget: OK (endless output, deadline accuracy, "
         "descendant reclaim, fd/zombie leaks, signalled child, cap canaries)");
    return 0;
}

/****************************************************************************
 * host_tests/agent_review/test_round_isolation.c
 *
 * Request correlation and result ownership for vg_agent_round.c.
 *
 * host_tests/test_agent_round.c already covers one timeout, one late
 * callback, the strict "consume before the next round" queue and recovery.
 * This file adds the parts of the contract that are still unproven, all of
 * them deterministic on a mocked clock:
 *
 *   - a request that never reaches the agent bus is released by the queue
 *     watchdog instead of holding the channel for the whole round budget;
 *   - a reply that arrives while the request is still QUEUED is kept, not
 *     dropped on the floor;
 *   - a submit failure isolates that round: the failed round's callback can
 *     neither mark the failed round as answered nor the next one;
 *   - reclaim() frees somebody else's finished-but-unread round only after
 *     the grace period, never the caller's own, never a running one;
 *   - the generation counter only advances on a reply, so a consumer can
 *     tell a fresh result from one it already handled;
 *   - the documented argument guards reject.
 ****************************************************************************/

#include <assert.h>
#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#include <velaclaw/client.h>

#include "vg_agent_round.h"

/* The request buffer is private to vg_agent_round.c.  These two lengths pin
 * its boundary from the outside: 1535 fits, 1536 must be refused. */
#define REQ_MAX 1536

/* ── mocked clock and agent client ─────────────────────────────────── */

static uint32_t now = 1000;

int __wrap_clock_gettime(clockid_t clock, struct timespec *ts)
{
    (void)clock;
    ts->tv_sec = now / 1000;
    ts->tv_nsec = (now % 1000) * 1000000;
    return 0;
}

static void (*cb_slot)(int, const char *, void *);
static void *cookie_slot;
static int ask_rc;
static int ask_calls;
static int open_ok = 1;

velaclaw_client_t *velaclaw_client_open(const char *name)
{
    (void)name;
    return open_ok ? (velaclaw_client_t *)(uintptr_t)1 : NULL;
}

int velaclaw_ask_async(velaclaw_client_t *c, const velaclaw_ask_req_t *req,
                       void (*cb)(int, const char *, void *), void *ck)
{
    (void)c;
    (void)req;
    ask_calls++;
    if (ask_rc != 0)
        return ask_rc;
    cb_slot = cb;
    cookie_slot = ck;
    return 0;
}

/* ── helpers ───────────────────────────────────────────────────────── */

#define STATE_IS(s) assert(vg_agent_round_state() == (s))

/* Queue, submit, and answer the round with `text`. */
static void complete_round(const char *text, enum vg_agent_round_owner owner)
{
    assert(vg_agent_round_queue_owned(text, owner) == 0);
    vg_agent_round_tick();                 /* QUEUED -> RUNNING */
    STATE_IS(VG_AGENT_ROUND_RUNNING);
    cb_slot(0, text, cookie_slot);
    vg_agent_round_tick();                 /* reply seen -> DONE */
    STATE_IS(VG_AGENT_ROUND_DONE);
}

/* ── tests ─────────────────────────────────────────────────────────── */

/* The bus never comes up: the round must be released by the queue watchdog,
 * and it must retry the open on every tick in the meantime. */
static void test_queue_watchdog_when_bus_is_down(void)
{
    open_ok = 0;

    assert(vg_agent_round_queue("boot") == 0);
    STATE_IS(VG_AGENT_ROUND_QUEUED);
    assert(vg_agent_round_busy());

    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_QUEUED);        /* still waiting for the bus */
    assert(ask_calls == 0);

    now += VG_AGENT_ROUND_QUEUE_TIMEOUT_MS / 2;
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_QUEUED);        /* grace not spent yet */

    now += VG_AGENT_ROUND_QUEUE_TIMEOUT_MS;
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_ERROR);         /* released, not left hanging */
    assert(!vg_agent_round_busy());
    assert(ask_calls == 0);

    vg_agent_round_clear();
    STATE_IS(VG_AGENT_ROUND_IDLE);

    open_ok = 1;
    ask_rc = 0;
}

static void test_argument_guards(void)
{
    static char big[REQ_MAX + 64];

    assert(vg_agent_round_queue(NULL) == -EINVAL);
    assert(vg_agent_round_queue("") == -EINVAL);
    STATE_IS(VG_AGENT_ROUND_IDLE);

    memset(big, 'a', sizeof(big) - 1);
    big[sizeof(big) - 1] = '\0';
    assert(vg_agent_round_queue(big) == -E2BIG);
    STATE_IS(VG_AGENT_ROUND_IDLE);          /* a refused request changes nothing */

    big[REQ_MAX - 1] = '\0';                /* exactly REQ_MAX - 1 bytes */
    assert(strlen(big) == REQ_MAX - 1);
    assert(vg_agent_round_queue(big) == 0);
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_RUNNING);

    /* Abandon it; the late reply for this round is used by the next test. */
    now += VG_AGENT_ROUND_TIMEOUT_MS;
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_ERROR);
    vg_agent_round_clear();
    STATE_IS(VG_AGENT_ROUND_IDLE);
}

/* A stale callback from an abandoned round must not touch the new one. */
static void test_late_callback_cannot_cross_rounds(void)
{
    void (*old_cb)(int, const char *, void *) = cb_slot;
    void *old_cookie = cookie_slot;
    uint32_t gen_before;

    complete_round("first", VG_AGENT_ROUND_OWNER_ADVICE);
    gen_before = vg_agent_round_generation();
    assert(vg_agent_round_owner() == VG_AGENT_ROUND_OWNER_ADVICE);
    assert(!strcmp(vg_agent_round_last_reply(), "first"));

    /* A terminal result is not free until its owner reads it. */
    assert(vg_agent_round_queue("blocked") == -EBUSY);
    STATE_IS(VG_AGENT_ROUND_DONE);

    vg_agent_round_clear();
    STATE_IS(VG_AGENT_ROUND_IDLE);
    assert(vg_agent_round_owner() == VG_AGENT_ROUND_OWNER_NONE);
    assert(vg_agent_round_generation() == gen_before);

    assert(vg_agent_round_queue_owned("second", VG_AGENT_ROUND_OWNER_DAILY) == 0);
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_RUNNING);

    /* The reply of the previous round arrives now. */
    old_cb(0, "stale", old_cookie);
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_RUNNING);       /* not mistaken for an answer */
    assert(vg_agent_round_generation() == gen_before);

    cb_slot(0, "fresh", cookie_slot);
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_DONE);
    assert(vg_agent_round_generation() == gen_before + 1);
    assert(!strcmp(vg_agent_round_last_reply(), "fresh"));

    /* A duplicate of the current reply is ignored as well. */
    cb_slot(0, "again", cookie_slot);
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_DONE);
    assert(vg_agent_round_generation() == gen_before + 1);
    assert(!strcmp(vg_agent_round_last_reply(), "fresh"));

    vg_agent_round_clear();
}

/* A reply that beats the submit must be kept, not dropped. */
static void test_reply_while_queued_is_kept(void)
{
    uint32_t gen_before = vg_agent_round_generation();

    assert(vg_agent_round_queue("early") == 0);
    STATE_IS(VG_AGENT_ROUND_QUEUED);

    /* The agent answers before the next tick hands the request over.  The
     * client cannot have produced this callback yet in a real build, but the
     * round must not lose it if it does. */
    vg_agent_round_tick();                  /* submit -> RUNNING */
    STATE_IS(VG_AGENT_ROUND_RUNNING);

    cb_slot(0, "early-answer", cookie_slot);
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_DONE);
    assert(vg_agent_round_generation() == gen_before + 1);
    assert(!strcmp(vg_agent_round_last_reply(), "early-answer"));

    vg_agent_round_clear();
}

/* A rejected submit is a terminal error for that round only. */
static void test_submit_failure_is_isolated(void)
{
    void (*previous_cb)(int, const char *, void *) = cb_slot;
    void *previous_cookie = cookie_slot;
    uint32_t gen_before = vg_agent_round_generation();
    int calls_before = ask_calls;

    ask_rc = -EBUSY;                        /* the client still thinks it is busy */
    assert(vg_agent_round_queue_owned("doomed", VG_AGENT_ROUND_OWNER_DAILY) == 0);
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_ERROR);
    assert(ask_calls == calls_before + 1);
    assert(vg_agent_round_generation() == gen_before);   /* no reply, no bump */

    /* The old round's callback must not turn the failure into a success. */
    previous_cb(0, "ghost", previous_cookie);
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_ERROR);
    assert(vg_agent_round_generation() == gen_before);

    vg_agent_round_clear();
    ask_rc = 0;

    /* Recovery: the channel is usable again and the ghost cannot leak into
     * the round that follows either. */
    assert(vg_agent_round_queue_owned("after", VG_AGENT_ROUND_OWNER_ADVICE) == 0);
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_RUNNING);
    previous_cb(0, "ghost again", previous_cookie);
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_RUNNING);

    cb_slot(0, "after-answer", cookie_slot);
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_DONE);
    assert(!strcmp(vg_agent_round_last_reply(), "after-answer"));
    vg_agent_round_clear();
}

static void test_reclaim_semantics(void)
{
    uint32_t gen_before = vg_agent_round_generation();

    complete_round("daily", VG_AGENT_ROUND_OWNER_DAILY);
    assert(vg_agent_round_generation() == gen_before + 1);

    /* The owner's own result is never reclaimed, at any age. */
    assert(!vg_agent_round_reclaim(VG_AGENT_ROUND_OWNER_DAILY, 30000));
    now += 600000;
    assert(!vg_agent_round_reclaim(VG_AGENT_ROUND_OWNER_DAILY, 30000));
    STATE_IS(VG_AGENT_ROUND_DONE);

    /* Somebody else's result is only freed once the grace period is spent. */
    now += 1;
    assert(!vg_agent_round_reclaim(VG_AGENT_ROUND_OWNER_ADVICE,
                                   600000 + 1));
    assert(vg_agent_round_reclaim(VG_AGENT_ROUND_OWNER_ADVICE, 1));
    STATE_IS(VG_AGENT_ROUND_IDLE);
    assert(vg_agent_round_owner() == VG_AGENT_ROUND_OWNER_NONE);
    assert(vg_agent_round_generation() == gen_before + 1);   /* result kept */

    /* Nothing to reclaim while idle. */
    assert(!vg_agent_round_reclaim(VG_AGENT_ROUND_OWNER_ADVICE, 0));

    /* A running round is never reclaimed, however long the caller waits. */
    assert(vg_agent_round_queue_owned("running", VG_AGENT_ROUND_OWNER_DAILY) == 0);
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_RUNNING);
    now += 600000;
    assert(!vg_agent_round_reclaim(VG_AGENT_ROUND_OWNER_ADVICE, 0));
    STATE_IS(VG_AGENT_ROUND_RUNNING);

    cb_slot(0, "running-answer", cookie_slot);
    vg_agent_round_tick();
    STATE_IS(VG_AGENT_ROUND_DONE);
    assert(vg_agent_round_reclaim(VG_AGENT_ROUND_OWNER_ADVICE, 0));
    STATE_IS(VG_AGENT_ROUND_IDLE);
}

int main(void)
{
    test_queue_watchdog_when_bus_is_down();
    test_argument_guards();
    test_late_callback_cannot_cross_rounds();
    test_reply_while_queued_is_kept();
    test_submit_failure_is_isolated();
    test_reclaim_semantics();

    puts("test_round_isolation: OK (queue watchdog, stale/duplicate replies, "
         "early reply, submit failure isolation, reclaim)");
    return 0;
}

